private double meleeHitProbability(Enemy e, double d) {
    double observed = (e.brain.actualHits + 2.0) / (e.brain.actualShots + 8.0);
    double geometry = clamp(0.08, 0.82 - d / 1100.0 - Math.abs(e.velocity) * 0.025
            - Math.abs(e.turnRate) * 0.5, 0.85);
    double weight = Math.min(0.7, e.brain.actualShots / (e.brain.actualShots + 18));
    return clamp(0.05, geometry * (1 - weight) + observed * weight, 0.9);
}

private double meleePower(Enemy e, double d, double probability) {
    double power = d < 220 ? 2.8 : d < 400 ? 2.4 : d < 550 ? 1.8 : 1.25;
    if (probability < 0.2) power *= 0.7;
    if (Math.abs(e.velocity) < 0.1 && d < 450) power = Math.max(power, 2.5);
    double lethal = e.energy <= 4 ? e.energy / 4 : (e.energy + 2) / 6;
    return clamp(0.1, Math.min(power, lethal + 0.02), 3);
}

